<script lang="ts">
  import {onDestroy} from 'svelte';
  import {request,display} from '#lib/client/api.ts';
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import type {AppData} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  let {data,filters,onclose}:{data:AppData;filters:URLSearchParams;onclose:()=>void}=$props();
  let password=$state('');let busy=$state(false);let error=$state('');let downloadUrl=$state('');
  const filename=$derived((data.module?.slug||'Auswertung')+'.csv');
  const descriptions:Record<string,string>={metric:'Kennzahl',q:'Suchbegriff',status:'Status',from:'Zeitraum von',to:'Zeitraum bis',business_unit:'Geschäftsbereich',bucket:'Fälligkeitsgruppe',currency:'Währung',disputed:'Strittigkeit',as_of:'Fälligkeitsstichtag',product_id:'Materialauswahl',required_on:'Bedarf am',unallocated:'Ohne Belegzuordnung',direction:'Zahlungsrichtung',order_id:'Auftrag'};
  const shownFilters=$derived(Array.from(filters.entries()).filter(([key])=>key!=='kind'&&descriptions[key]));
  async function prepare(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';try{await request('/api/v1/reauth',{password});password='';const response=await fetch('/api/v1/exports?'+filters,{credentials:'same-origin',headers:{Accept:'text/csv'}});if(!response.ok){const result=await response.json().catch(()=>null);throw new Error(result?.error?.message||result?.message||'Die berechtigte Exportdatei konnte nicht erstellt werden.');}const blob=await response.blob();if(downloadUrl)URL.revokeObjectURL(downloadUrl);downloadUrl=URL.createObjectURL(blob);}catch(cause){error=cause instanceof Error?cause.message:'Die Exportdatei konnte nicht geladen werden.';}finally{busy=false;}}
  onDestroy(()=>{if(downloadUrl)URL.revokeObjectURL(downloadUrl);});
</script>
<div class="modal-backdrop" role="presentation" onclick={(event)=>{if(event.target===event.currentTarget&&!busy)onclose();}}><div class="modal" role="dialog" tabindex="-1" aria-modal="true" aria-labelledby="export-title" use:focusTrap onkeydown={(event)=>{if(event.key==='Escape'&&!busy)onclose();}}><header class="modal-header"><div><h2 id="export-title">{data.module?.label} exportieren</h2><p>Nur der berechtigte Bestand mit den unten angezeigten Filtern wird ausgegeben.</p></div><button class="icon-button" aria-label="Schließen" disabled={busy} onclick={onclose}><Icon name="close"/></button></header><form onsubmit={prepare} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}<dl class="definition-list"><div><dt>Bereich</dt><dd>{data.module?.label}</dd></div><div><dt>Format</dt><dd>CSV · für Tabellenprogramme</dd></div>{#each shownFilters as [key,value]}<div><dt>{descriptions[key]}</dt><dd>{display(value,['from','to','as_of','required_on'].includes(key)?'date':key,data)}</dd></div>{/each}</dl><p class="field-help mt">{shownFilters.length?'Die Filter entsprechen Ihrer aktuellen Ansicht.':'Ohne zusätzliche Filter wird der aktuell berechtigte Listenbestand ausgegeben.'} Die Datei enthält vertrauliche betriebliche Angaben. Speichern Sie sie an einem dafür vorgesehenen Ort.</p>{#if downloadUrl}<div class="notice info mt" role="status"><Icon name="check"/><div>Die CSV-Datei wurde aus dem berechtigten Serverbestand erzeugt. Sie können sie jetzt herunterladen.</div></div>{:else}<div class="field mt"><label for="export-password">Eigene Passphrase bestätigen *</label><input id="export-password" type="password" bind:value={password} autocomplete="current-password" required/><span class="field-help">Für diesen Datenexport bestätigen Sie Ihre persönliche Anmeldung erneut.</span></div>{/if}</div><footer class="modal-footer"><button type="button" class="btn" disabled={busy} onclick={onclose}>{downloadUrl?'Schließen':'Abbrechen'}</button>{#if downloadUrl}<a class="btn primary" href={downloadUrl} download={filename} data-sveltekit-reload><Icon name="download" size={16}/>CSV herunterladen</a>{:else}<button class="btn primary" type="submit" disabled={busy}><Icon name={busy?'refresh':'download'} size={16} class={busy?'spin':''}/>{busy?'Wird geprüft und geladen …':'Exportdatei vorbereiten'}</button>{/if}</footer></form></div></div>
